def sight_of(text):
    t = text or ''
    best = None
    for k, v in SIGHT.items():
        if k in t and not _den('SIGHT', k) and (best is None or len(k) > len(best[0])): best = (k, v)     # 最长的键优先：“沈阳故宫”不能拿到“故宫”的介绍
    return best[1] if best else None


