def ctrip_city(c):
    for k in (c, (c or '') + '市', (c or '') + '县', (c or '') + '地区', (c or '').rstrip('市县')):
        if k in CT['city']: return CT['city'][k]
    for k in (c, (c or '') + '县', (c or '') + '市', (c or '') + '镇'):
        if k in CT['district']: return CT['district'][k]
    return None


def hotel_url(keyword, city, app='amap', base=None):
    """订酒店链接：携程手机版要带城市编号才按关键词搜（不带会默认显示上海）；携程查不到这个城市就用地图搜酒店"""
    cid = ctrip_city(city) or ctrip_city(CT_ALIAS.get(city, '')) or (ctrip_city(base) if base else None)
    if cid: return f'https://m.ctrip.com/webapp/hotels/list?city={cid}&keyword={urllib.parse.quote(keyword)}'
    if app == 'google': return 'https://www.google.com/maps/search/?api=1&query=' + urllib.parse.quote(keyword + ' hotel')
    return 'https://uri.amap.com/search?keyword=' + urllib.parse.quote(keyword) + '&city=' + urllib.parse.quote(city or '') + '&src=zouni&callnative=1'


GENERIC_STAY = re.compile(r'(附近|市区|县城|老城|古城|市中心|城里|边上|一带|营地|客栈|民宿)$')


def _km(a, b):
    import math as _m
    r = _m.pi / 180; dl = (b[1] - a[1]) * r; p1, p2 = a[0] * r, b[0] * r
    return 2 * 6371 * _m.asin(_m.sqrt(_m.sin((p2 - p1) / 2) ** 2 + _m.cos(p1) * _m.cos(p2) * _m.sin(dl / 2) ** 2))


def stay_fix(r):
    """每天晚上实际住哪：返回 [(住处名, 回住处的交通说明或 None)]
    只改一种明确的错：当天已经到了下一个地方（离前一天最后一站 60 公里以上、第二天也从这附近出发），住处却还写着前一天那家；
    回住处的车程只在 30–120 公里之间、两头坐标都可信时才写"""
    out = []; n_ = len(r['days'])
    def pts(d):
        c = d.get('navCity') or d.get('city')
        return [coord(w['poi'], c) for w in d['rows'] if w['type'] in ('see', 'fun', 'eat') and w.get('poi') and coord(w['poi'], c)]
    P = [pts(d) for d in r['days']]
    prev_nm = None
    for i, d in enumerate(r['days']):
        nm = d['stay'][0]['name'] if d.get('stay') else d.get('stayName')
        if i == n_ - 1 or not nm or d.get('stay'): out.append((nm, None)); prev_nm = nm; continue
        city = d.get('navCity') or d.get('city'); last = P[i][-1] if P[i] else None
        plast = P[i - 1][-1] if i > 0 and P[i - 1] else None; nf = P[i + 1][0] if P[i + 1] else None
        if prev_nm and nm == prev_nm and last and plast and _km(last, plast) > 60 and (nf is None or _km(last, nf) < 60):
            pcity = r['days'][i - 1].get('navCity') or r['days'][i - 1].get('city')
            if city and city != pcity: nm = city + '附近'
        how = None
        cc = GEO.get((city or '') + '|' + (city or '')); ccp = (cc['lat'], cc['lng']) if cc else None
        core = GENERIC_STAY.sub('', nm or '').strip()
        sp = coord(core, city) or coord(nm, city) or (ccp if core in ('', city) else None)
        if sp and ccp and _km(sp, ccp) > 80: sp = None
        if last and sp and 30 < _km(last, sp) <= 120:
            out0 = next((w['how'] for w in d['rows'] if w['type'] == 'dep' and w.get('how')), '') or ''
            if plast and P[i] and _km(plast, P[i][0]) > 100: out0 = ''       # 转场日：第一段是从上一座城过来的高铁，不是“当天往返”的去程，回住处不能照抄（slgt8 晚上 3 小时 30 分高铁回住处）
            if re.search(r'JR|高铁|动车|火车|地铁|轮渡|坐船|公交|大巴|快艇', out0):
                how = re.split(r'\s*·\s*', out0)[0]            # 去的时候坐什么，回来也坐什么
            else:
                mins = int(_km(last, sp) * 1.3)
                how = ('包车约 ' + (f'{mins // 60} 小时' + (f' {mins % 60} 分' if mins % 60 >= 10 else '') if mins >= 60 else f'{mins} 分钟') + f' · {round(_km(last, sp) * 1.3)} 公里')
        if nm in ('古城', '老城', '市区', '市中心', '县城', '城里', '新城') and city: nm = city + nm
        out.append((nm, how)); prev_nm = d['stay'][0]['name'] if d.get('stay') else d.get('stayName')
    return out


DAY_PT = {}


def day_point(rr, k):
    key = (id(rr), k)
    if key in DAY_PT: return DAY_PT[key]
    d = rr['days'][k]; c = d.get('navCity') or d.get('city')
    ps = [coord(w['poi'], c) for w in d['rows'] if w['type'] in ('see', 'fun') and w.get('poi') and coord(w['poi'], c)]
    cc = GEO.get((c or '') + '|' + (c or ''))
    if cc: ps = [p_ for p_ in ps if _km(p_, (cc['lat'], cc['lng'])) < 150] or [(cc['lat'], cc['lng'])]   # 按名字查到外地同名的点不算
    DAY_PT[key] = (sum(p[0] for p in ps) / len(ps), sum(p[1] for p in ps) / len(ps)) if ps else None
    return DAY_PT[key]


_CAND_POOL = None
_core = lambda x: re.split(r'\s*·\s*', x or '')[0].strip()


def _cand_pool():
    """所有可以“接上”的一天（别的线里不是赶路、不是回程的天），只算一次"""
    global _CAND_POOL
    if _CAND_POOL is None:
        pool = []
        for o, rr in ROUTES.items():
            for k, dd in enumerate(rr['days']):
                ttl = dd.get('title') or ''
                if re.search(r'回|→|出发|去|到达|抵达|还车|提车', ttl): continue
                pt = day_point(rr, k) or ((dd['lat'], dd['lng']) if dd.get('lat') and dd.get('lng') else None)   # 景点没坐标的，用这一天的落脚点
                if not pt: continue
                names = [w.get('name') for w in dd['rows'] if w['type'] in ('see', 'fun')]
                if not names: continue
                pool.append((o, k, ttl, pt, [_core(x) for x in names], rr.get('label')))
        _CAND_POOL = pool
    return _CAND_POOL


def add_cands(rid, r):
    """加一天的候选：离这条线每一天（最后一天除外）100 公里以内的、别的线里的一天；d 记“离第几天多远”，在哪天后面加就按离那天的远近排"""
    n_ = len(r['days'])
    if n_ < 2: return []
    pts = [day_point(r, k) or ((r['days'][k]['lat'], r['days'][k]['lng']) if r['days'][k].get('lat') and r['days'][k].get('lng') else None) for k in range(n_ - 1)]
    mine = {_core(w.get('name')) for d in r['days'] for w in d['rows'] if w['type'] in ('see', 'fun')}
    best = []
    for (o, k, ttl, pt, cores, label) in _cand_pool():
        if o == rid: continue
        if sum(1 for x in cores if x in mine) >= max(1, len(cores) // 2 + (len(cores) % 2)): continue   # 一半以上已经在这条线里
        dd = {}
        for j, bp in enumerate(pts):
            if not bp or abs(bp[0] - pt[0]) > 1.0 or abs(bp[1] - pt[1]) > 1.4: continue
            km = _km(bp, pt)
            if km <= 100: dd[j] = round(km)
        if dd: best.append({'rid': o, 'label': label, 'i': k, 'title': ttl, 'lat': round(pt[0], 4), 'lng': round(pt[1], 4), 'd': dd, 'km': min(dd.values())})
    best.sort(key=lambda x: x['km'])
    seen = set(); res = []
    for x in best:
        if x['title'] in seen: continue
        seen.add(x['title']); res.append(x)
    keep = set()
    for j in range(n_ - 1):
        for x in sorted([x for x in res if j in x['d']], key=lambda x: x['d'][j])[:10]: keep.add(id(x))
    return [x for x in res if id(x) in keep]


HOTELS = json.load(open('data/hotels/ctrip_hotels.json')) if os.path.exists('data/hotels/ctrip_hotels.json') else {}


def hotel_pick(city, area):
    """携程上这个住处的真实酒店（抓下来的）：返回 (三档, 高分列表)"""
    cid = ctrip_city(city) or ctrip_city(CT_ALIAS.get(city, ''))
    if not cid: return None, None
    kw = re.sub(r'(附近|一带|边上|边|里|市区)$', '', area) if area and area != city else city
    h = HOTELS.get(f'{cid}|{kw}') or {}
    return ({k: h[k] for k in ('lux', 'mid', 'eco') if h.get(k)} or None), (h.get('top') or None)


def ctrip_detail(hid): return f'https://m.ctrip.com/html5/hotel/hoteldetail/{hid}.html'


def kfmt(v):
    v = round(v / 100) / 10
    return (f'{v:.1f}'.rstrip('0').rstrip('.')) if v < 100 else f'{v:.0f}'


def price_k(p):
    """¥2,800–3,800 → ¥2.8–3.8K（短，放得下）"""
    ns = [int(x.replace(',', '')) for x in re.findall(r'\d[\d,]*', p or '')]
    if not ns: return p or ''
    return '¥' + (kfmt(ns[0]) + 'K–' + kfmt(ns[1]) + 'K' if len(ns) > 1 else kfmt(ns[0]) + 'K')


TIX = json.load(open('data/catalog/tickets.json')) if os.path.exists('data/catalog/tickets.json') else {}
INDOOR_RE = re.compile(r'博物馆|博物院|美术馆|纪念馆|展览馆|科技馆|陈列馆|艺术馆|天文馆|海洋馆|水族馆')


def tix_of(name):
    n_ = name or ''
    k = next((k for k in sorted(TIX, key=len, reverse=True) if k in n_ and not _den('TIX', k)), None)
    return TIX[k] if k else None


INDOOR = []


def indoor_list():
    """所有行程里出现过、有坐标的室内去处（下雨时换着去）"""
    if INDOOR: return INDOOR
    seen = set()
    for rr in ROUTES.values():
        for d in rr['days']:
            c = d.get('navCity') or d.get('city')
            for w in d['rows']:
                nm = w.get('name') or ''
                if w['type'] in ('see', 'fun') and INDOOR_RE.search(nm) and w.get('poi'):
                    core = re.split(r'\s*·\s*', nm)[0]
                    if core in seen: continue
                    pt = coord(w['poi'], c)
                    if pt: seen.add(core); INDOOR.append({'n': core, 'q': w['poi'], 'c': c, 'lat': round(pt[0], 4), 'lng': round(pt[1], 4)})
    return INDOOR


def indoor_near(r):
    pts = [p_ for k in range(len(r['days'])) for p_ in [day_point(r, k)] if p_]
    mine = {re.split(r'\s*·\s*', w.get('name') or '')[0] for d in r['days'] for w in d['rows']}
    out = []
    for x in indoor_list():
        if x['n'] in mine: continue
        dmin = min((_km((x['lat'], x['lng']), p_) for p_ in pts), default=999)
        if dmin <= 60: out.append(dict(x, km=round(dmin)))
    out.sort(key=lambda x: x['km'])
    return out[:20]


NEAR = []


def near_list():
    if NEAR: return NEAR
    seen = set()
    for rr in ROUTES.values():
        for d in rr['days']:
            c = d.get('navCity') or d.get('city')
            for w in d['rows']:
                nm = w.get('name') or ''
                if w['type'] not in ('see', 'fun') or not w.get('poi') or '沿途' in nm or '提车' in nm or '还车' in nm: continue
                core = re.split(r'\s*·\s*', nm)[0]
                if core in seen: continue
                pt = coord(w['poi'], c)
                if not pt: continue
                m_ = re.search(r'(\d+) 小时', w.get('d') or ''); m2 = re.search(r'(\d+) 分', w.get('d') or '')
                dur = (int(m_.group(1)) * 60 if m_ else 0) + (int(m2.group(1)) if m2 else 0) or 90
                seen.add(core); NEAR.append({'n': core, 'c': c, 'lat': round(pt[0], 4), 'lng': round(pt[1], 4), 'dur': dur})
    return NEAR


def near_for(r):
    pts = [p_ for k in range(len(r['days'])) for p_ in [day_point(r, k)] if p_]
    mine = {re.split(r'\s*·\s*', w.get('name') or '')[0] for d in r['days'] for w in d['rows']}
    out = []
    for x in near_list():
        if x['n'] in mine: continue
        dmin = min((_km((x['lat'], x['lng']), p_) for p_ in pts), default=999)
        if dmin <= 25: out.append(x)
    out.sort(key=lambda x: min(_km((x['lat'], x['lng']), p_) for p_ in pts))
    return out[:30]


def addday_city(r, SF):
    """加一天时“在哪多留一天”：住处名像酒店（酒店、宾馆、民宿、客栈……）就用城市名"""
    nm = (SF[-2][0] if len(SF) > 1 and SF[-2][0] else '') or ''
    city = (r['days'][-2].get('navCity') or r['days'][-2].get('city')) if len(r['days']) > 1 else (r['days'][0].get('navCity') or r['days'][0].get('city'))
    if not nm or re.search(r'酒店|宾馆|饭店|民宿|客栈|旅舍|度假村|山庄|公寓', nm): return city or nm
    return nm


RCENT = {}


def route_center(o):
    if o in RCENT: return RCENT[o]
    rr = ROUTES[o]; ps = [p_ for k in range(len(rr['days'])) for p_ in [day_point(rr, k)] if p_]
    RCENT[o] = (sum(p_[0] for p_ in ps) / len(ps), sum(p_[1] for p_ in ps) / len(ps)) if ps else None
    return RCENT[o]


def nearby_routes(rid, k=3):
    """附近还能去：离这条线中心最近的几条（不含自己、不含跨省全国长线，同一目的地最多一条）"""
    c0 = route_center(rid)
    if not c0: return []
    out = []
    for o in ROUTE_IDS:
        if o == rid or not TRIP_OF_ROUTE.get(o): continue
        if set(TRIP_OF_ROUTE[o].get('tags') or []) & {'跨省', '全国'}: continue
        c1 = route_center(o)
        if not c1: continue
        dk = _km(c0, c1)
        if dk < 5 or dk > 600: continue
        out.append((dk, o))
    out.sort(); res = []; seen = set()
    for dk, o in out:
        lab = re.sub(r'\s*\d+\s*天$', '', ROUTES[o].get('label') or '')
        if lab in seen: continue
        seen.add(lab); res.append((dk, o))
        if len(res) >= k: break
    return res


